-- =====================================================================
-- AFAMSHOP — Intégration du retour client du 01/10/2026
--  * Retrait des mentions de partenariat Sharp (textes, bannières, page AFAM × Sharp)
--  * Bloc d'accueil « Logiciel de gestion de parc » + fiche produit du logiciel AFAM (Informatique › Réseau)
--  * Nouveau service « Impression multisupport »
--  * Page « À propos » enrichie, description des kits de maintenance
--  * Paiement par carte bancaire via PayDunya
-- Les textes déjà personnalisés dans l'admin ne sont pas écrasés (sauf la page À propos).
-- La dernière requête liste les mentions de Sharp qui resteraient à corriger à la main.
-- =====================================================================
SET NAMES utf8mb4;

-- 1. Textes sans référence au partenariat Sharp (uniquement s'ils n'ont pas été modifiés)
UPDATE settings SET svalue = 'Livraison rapide à Dakar et en régions • Paiement par carte, Wave et Orange Money' WHERE skey = 'topbar_text' AND svalue = 'Livraison rapide à Dakar • Représentant exclusif Sharp au Sénégal';
UPDATE settings SET svalue = 'Imprimantes, copieurs, consommables, informatique et fournitures de bureau. Vente, location, maintenance et impression multisupport clé en main avec AFAM.' WHERE skey = 'hero_subtitle' AND svalue = 'Imprimantes, copieurs, consommables, informatique et fournitures de bureau. Vente, location et maintenance clé en main avec AFAM, représentant exclusif Sharp au Sénégal.';
UPDATE settings SET svalue = 'Des multifonctions performantes en location clé en main : matériel, consommables et maintenance inclus dans un loyer maîtrisé.' WHERE skey = 'home_rental_text' AND svalue = 'Des multifonctions Sharp performantes en location clé en main : matériel, consommables et maintenance inclus dans un loyer maîtrisé.';
UPDATE settings SET svalue = 'Imprimantes, copieurs, toners, cartouches, informatique, fournitures de bureau et impression multisupport au Sénégal. Vente, location et maintenance.' WHERE skey = 'meta_description' AND svalue = 'Imprimantes, copieurs Sharp, toners, cartouches, informatique et fournitures de bureau au Sénégal. Vente, location et maintenance.';
UPDATE settings SET svalue = REPLACE(REPLACE(svalue, ' • Représentant exclusif Sharp au Sénégal', ''), ', représentant exclusif Sharp au Sénégal', '') WHERE sgroup IN ('header','home','footer','seo','general');

-- 2. Bloc d'accueil Sharp remplacé par le bloc « Logiciel de gestion de parc »
DELETE FROM settings WHERE skey IN ('home_sharp_title', 'home_sharp_text', 'home_sharp_image');
INSERT IGNORE INTO settings (skey, svalue, sgroup, label, type, sort) VALUES ('home_software_title', 'Logiciel de gestion de parc d\'imprimantes AFAM', 'home', 'Bloc logiciel : titre', 'text', 62);
INSERT IGNORE INTO settings (skey, svalue, sgroup, label, type, sort) VALUES ('home_software_text', 'Supervisez toutes vos imprimantes depuis un seul tableau de bord : niveaux de toner, compteurs, alertes et rapports de coûts. Une solution développée par AFAM pour réduire vos coûts d\'impression.', 'home', 'Bloc logiciel : texte', 'textarea', 63);
INSERT IGNORE INTO settings (skey, svalue, sgroup, label, type, sort) VALUES ('home_software_button', 'Découvrir le logiciel', 'home', 'Bloc logiciel : texte du bouton', 'text', 64);
INSERT IGNORE INTO settings (skey, svalue, sgroup, label, type, sort) VALUES ('home_software_link', 'produit/logiciel-gestion-parc-imprimantes', 'home', 'Bloc logiciel : lien du bouton', 'text', 65);
INSERT IGNORE INTO settings (skey, svalue, sgroup, label, type, sort) VALUES ('home_software_image', 'assets/img/contenus/home-logiciel.jpg', 'home', 'Bloc logiciel : image', 'image', 66);
INSERT IGNORE INTO settings (skey, svalue, sgroup, label, type, sort) VALUES ('payment_paydunya_card_enabled', '1', 'payment', 'Proposer la carte bancaire via PayDunya (si Stripe n\'est pas configuré)', 'bool', 101);

-- 3. Pages : suppression de « AFAM × Sharp », À propos enrichie, mentions légales
DELETE FROM pages WHERE slug = 'afam-sharp';
INSERT INTO pages (slug, title, content, footer_group, published, sort) VALUES ('a-propos', 'À propos', '<div class=\"about-intro\">\n<p class=\"lead\"><strong>{company_name}</strong> est une entreprise sénégalaise spécialisée dans les solutions d\'impression et les équipements de bureau pour les entreprises, les administrations et les particuliers. Vente, location, maintenance, consommables, informatique et impression multisupport : nous accompagnons nos clients sur l\'ensemble de leurs besoins documentaires, avec un objectif constant — <strong>performance, économies et respect de l\'environnement</strong>.</p>\n</div>\n\n<h2>Notre histoire</h2>\n<p>Créée en <mark class=\"todo\">[année de création]</mark> à Dakar, {company_name} est née d\'une conviction : les entreprises sénégalaises méritent des solutions d\'impression fiables, accompagnées d\'un service de proximité réactif. <mark class=\"todo\">[Quelques lignes sur les fondateurs, les grandes étapes et l\'évolution de l\'entreprise.]</mark></p>\n<p>Au fil des années, {company_name} a élargi son offre de la vente de matériel à la location clé en main, à la maintenance, aux consommables, à l\'informatique professionnelle, à l\'impression multisupport et au développement de son propre logiciel de gestion de parc d\'imprimantes.</p>\n\n<h2>Nos chiffres clés</h2>\n<div class=\"about-stats\">\n<div><strong><mark class=\"todo\">[XX]</mark></strong><span>années d\'expérience</span></div>\n<div><strong><mark class=\"todo\">[XXX]</mark></strong><span>clients entreprises et administrations</span></div>\n<div><strong><mark class=\"todo\">[XXX]</mark></strong><span>équipements installés et suivis</span></div>\n<div><strong><mark class=\"todo\">[XX]</mark></strong><span>techniciens et collaborateurs</span></div>\n</div>\n\n<h2>Nos valeurs</h2>\n<div class=\"about-grid\">\n<div class=\"about-card\"><h3>Proximité</h3><p>Une équipe locale, disponible et à l\'écoute, qui connaît les réalités de nos clients.</p></div>\n<div class=\"about-card\"><h3>Fiabilité</h3><p>Du matériel et des consommables d\'origine, des engagements tenus, des délais respectés.</p></div>\n<div class=\"about-card\"><h3>Expertise</h3><p>Des conseillers et techniciens formés, capables de proposer la solution la plus adaptée et la plus économique.</p></div>\n<div class=\"about-card\"><h3>Responsabilité</h3><p>Des équipements économes en énergie, la réduction des impressions inutiles et la collecte des consommables usagés.</p></div>\n</div>\n\n<h2>Notre expertise et nos domaines d\'activité</h2>\n<ul>\n<li><strong>Vente de matériel</strong> : imprimantes, multifonctions, copieurs, traceurs, ordinateurs et équipements informatiques des grandes marques.</li>\n<li><strong>Location clé en main</strong> : multifonctions installées, entretenues et approvisionnées en consommables pour un loyer maîtrisé.</li>\n<li><strong>Maintenance</strong> : préventive et corrective, remplacement de pièces, assistance sur site et à distance.</li>\n<li><strong>Consommables</strong> : toners, cartouches, tambours, kits de maintenance et papeterie, avec recherche par modèle d\'imprimante.</li>\n<li><strong>Impression multisupport</strong> : documents, supports de communication, grand format et signalétique.</li>\n<li><strong>Logiciel de gestion de parc</strong> : solution développée par {company_name} pour superviser les imprimantes, suivre les volumes et anticiper les besoins en consommables.</li>\n</ul>\n\n<h2>Nos engagements qualité et service</h2>\n<div class=\"about-grid\">\n<div class=\"about-card\"><h3>Produits authentiques</h3><p>Des consommables et pièces d\'origine ou de qualité équivalente garantie, pour préserver la durée de vie de vos équipements.</p></div>\n<div class=\"about-card\"><h3>Réactivité</h3><p>Une prise en charge rapide des demandes d\'intervention, à Dakar et dans les régions.</p></div>\n<div class=\"about-card\"><h3>Transparence</h3><p>Des devis clairs, des contrats lisibles et un suivi de vos commandes et demandes depuis votre espace client.</p></div>\n<div class=\"about-card\"><h3>Accompagnement</h3><p>Conseil avant achat, installation, formation des utilisateurs et suivi dans la durée.</p></div>\n</div>\n\n<h2>Nos équipes et nos métiers</h2>\n<div class=\"about-grid\">\n<div class=\"about-card\"><h3>Conseil commercial</h3><p>Analyse des besoins, audit de parc, devis et accompagnement des entreprises et administrations.</p></div>\n<div class=\"about-card\"><h3>Service technique</h3><p>Installation, maintenance préventive et corrective, dépannage et remplacement de pièces.</p></div>\n<div class=\"about-card\"><h3>Logistique</h3><p>Gestion des stocks, préparation des commandes et livraison à Dakar et en régions.</p></div>\n<div class=\"about-card\"><h3>Développement et support</h3><p>Conception du logiciel de gestion de parc, assistance aux utilisateurs et support à distance.</p></div>\n</div>\n<p><mark class=\"todo\">[Optionnel : présentation de l\'équipe dirigeante, photos de l\'équipe.]</mark></p>\n\n<div class=\"about-cta\">\n<p><strong>Un projet, une question ?</strong> Nos conseillers vous répondent.</p>\n<p><a class=\"btn btn-accent\" href=\"{site_url}/devis\">Demander un devis</a> <a class=\"btn btn-outline\" href=\"{site_url}/contact\">Nous contacter</a></p>\n</div>\n', 'company', 1, 1)
ON DUPLICATE KEY UPDATE content = VALUES(content);
UPDATE pages SET content = REPLACE(content, ', représentant exclusif de la marque Sharp au Sénégal.', ' : vente, location, maintenance, consommables, informatique et impression multisupport.') WHERE slug = 'mentions-legales';
UPDATE pages SET content = REPLACE(content, '(notamment Sharp, Canon, HP, Ricoh)', '(notamment Canon, HP, Ricoh, Sharp)') WHERE slug = 'mentions-legales';

-- 4. Services : texte de la location, nouveau service « Impression multisupport »
UPDATE services SET content = REPLACE(content, 'multifonctions Sharp récentes', 'multifonctions récentes');
UPDATE services SET sort = sort + 1 WHERE sort >= 3 AND slug <> 'impression-multisupport' AND NOT EXISTS (SELECT 1 FROM (SELECT slug FROM services) s WHERE s.slug = 'impression-multisupport');
INSERT IGNORE INTO services (slug, title, icon, short_desc, content, image, form_type, sort, active) VALUES ('impression-multisupport', 'Impression multisupport', 'printer', 'Documents, supports de communication, grand format, signalétique : tous vos imprimés professionnels.', '<h2>Tous vos supports imprimés, au même endroit</h2>\n<p>Au-delà de l\'équipement de vos bureaux, {company_name} réalise vos impressions professionnelles sur une large gamme de supports, en petite comme en grande série, avec un rendu soigné et des délais maîtrisés.</p>\n\n<h3>Ce que nous imprimons</h3>\n<ul>\n<li><strong>Documents</strong> : rapports, mémoires, catalogues, brochures, impressions noir et blanc ou couleur en volume, reliure ;</li>\n<li><strong>Supports de communication</strong> : flyers, dépliants, affiches, cartes de visite, papier à en-tête, chemises, invitations ;</li>\n<li><strong>Grand format</strong> : affiches grand format, plans, posters, bâches et banderoles ;</li>\n<li><strong>Signalétique et événementiel</strong> : roll-up, kakémonos, autocollants et vinyles, panneaux.</li>\n</ul>\n\n<h3>Notre accompagnement</h3>\n<ul>\n<li>Conseil sur le choix des supports, formats et finitions ;</li>\n<li>Vérification des fichiers et bon à tirer avant impression ;</li>\n<li>Possibilité de mise en page à partir de vos éléments ;</li>\n<li>Retrait sur place ou livraison à Dakar et en régions.</li>\n</ul>\n\n<p>Décrivez votre projet dans le formulaire (type de support, format, quantité, délai) et joignez vos fichiers : nous vous adressons un devis rapidement.</p>\n', 'assets/img/contenus/service-multisupport.jpg', 'quote', 3, 1);

-- 5. Bannières sans référence à Sharp
UPDATE banners SET title = 'Jusqu''à -15 % sur les toners d''origine' WHERE title = 'Jusqu''à -15 % sur les toners Sharp';
UPDATE banners SET title = 'Multifonctions professionnelles', link = 'categorie/multifonctions', image_desktop = 'assets/img/contenus/slide-multifonctions.jpg' WHERE title = 'Multifonctions Sharp';
UPDATE banners SET image_desktop = 'assets/img/contenus/slide-multifonctions.jpg' WHERE image_desktop = 'assets/img/contenus/slide-sharp.jpg';

-- 6. Descriptions des catégories « Kits de maintenance » et « Réseau » (si vides)
UPDATE categories SET description = '<p>Les <strong>kits de maintenance</strong> regroupent les pièces d\'usure d\'origine à remplacer après un certain nombre de pages imprimées (unité de fusion, rouleaux d\'entraînement, unité de transfert, filtres…), selon les préconisations du constructeur. Ils prolongent la durée de vie de votre équipement et garantissent une qualité d\'impression constante.</p><p>Ces kits sont <strong>disponibles sur commande</strong> : indiquez-nous le modèle de votre imprimante, nous vous confirmons la référence, le prix et le délai. Leur installation peut être réalisée par nos techniciens dans le cadre d\'une <a href=\"{site_url}/service/maintenance\">prestation de maintenance</a>.</p>' WHERE slug = 'kits-de-maintenance' AND (description IS NULL OR description = '');
UPDATE categories SET description = '<p>Équipements réseau et solutions logicielles pour vos environnements d\'impression, dont le <a href=\"{site_url}/produit/logiciel-gestion-parc-imprimantes\"><strong>logiciel de gestion de parc d\'imprimantes développé par AFAM</strong></a> : supervision de vos équipements, suivi des consommables et des coûts. Démonstration gratuite sur demande.</p>' WHERE slug = 'reseau' AND (description IS NULL OR description = '');

-- 7. Logiciel de gestion de parc AFAM (fiche produit, prix sur devis)
INSERT IGNORE INTO brands (name, slug, featured, active, sort) VALUES ('AFAM', 'afam', 0, 1, 99);
INSERT IGNORE INTO products (sku, manufacturer_ref, name, slug, brand_id, category_id, product_type, short_description, description, specs, price, stock, warranty, delivery_delay, is_featured, published)
SELECT 'AF-LOG-PARC', 'AFAM-PARC', 'Logiciel de gestion de parc d\'imprimantes AFAM', 'logiciel-gestion-parc-imprimantes', (SELECT id FROM brands WHERE slug = 'afam'), (SELECT id FROM categories WHERE slug = 'reseau'), 'Logiciel', 'Supervisez toutes vos imprimantes depuis un tableau de bord unique : niveaux de consommables, compteurs, alertes et rapports de coûts. Solution multi-marques développée par AFAM.', '<p><strong>Le logiciel de gestion de parc d\'imprimantes développé par {company_name}</strong> vous donne une vue complète et en temps réel de tous vos équipements d\'impression, quelle que soit leur marque. Fini les pannes de toner imprévues et les coûts d\'impression mal maîtrisés.</p>\n\n<h3>Fonctionnalités principales</h3>\n<ul>\n<li><strong>Supervision centralisée</strong> : état de chaque imprimante (en service, en alerte, hors ligne) sur un seul tableau de bord ;</li>\n<li><strong>Niveaux de consommables</strong> : suivi des toners et cartouches, alertes avant épuisement et réapprovisionnement anticipé ;</li>\n<li><strong>Relevés de compteurs automatiques</strong> : volumes noir et blanc / couleur par équipement, par site ou par service ;</li>\n<li><strong>Alertes et incidents</strong> : notification des pannes et bourrages pour une intervention plus rapide ;</li>\n<li><strong>Rapports et statistiques</strong> : suivi des coûts, des volumes et de l\'utilisation pour optimiser votre parc ;</li>\n<li><strong>Multi-sites et multi-marques</strong> : compatible avec les principaux constructeurs.</li>\n</ul>\n\n<h3>Les bénéfices pour votre organisation</h3>\n<ul>\n<li>Réduction des coûts d\'impression et des immobilisations ;</li>\n<li>Continuité de service grâce à l\'anticipation des besoins ;</li>\n<li>Meilleure maîtrise budgétaire et visibilité pour la direction ;</li>\n<li>Démarche écoresponsable : moins de gaspillage de papier et de consommables.</li>\n</ul>\n\n<h3>Mise en œuvre</h3>\n<p>Installation et paramétrage par nos équipes, formation de vos utilisateurs et support inclus. Le logiciel peut être proposé seul ou intégré à un contrat de location ou de maintenance.</p>\n<p><strong>Tarif sur devis</strong> selon la taille de votre parc. Demandez une démonstration gratuite.</p>\n', 'Type: Logiciel de supervision de parc d\'impression\nÉditeur: AFAM\nCompatibilité: Multi-marques, multi-sites\nFonctions: Niveaux de consommables, compteurs, alertes, rapports\nDéploiement: Installation et paramétrage par AFAM\nFormation et support: Inclus\nTarif: Sur devis', 0, 0, 'Support et mises à jour inclus', 'Mise en service sur rendez-vous', 1, 1;
INSERT INTO product_images (product_id, path, alt, is_main, sort)
SELECT p.id, 'assets/img/contenus/logiciel-produit.jpg', 'Logiciel de gestion de parc d\'imprimantes AFAM', 1, 0 FROM products p WHERE p.sku = 'AF-LOG-PARC'
AND NOT EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = p.id);

-- 8. Vérification : mentions de Sharp restant dans les contenus (hors catalogue produits)
SELECT 'Paramètre' COLLATE utf8mb4_unicode_ci AS type, skey COLLATE utf8mb4_unicode_ci AS element, LEFT(svalue, 120) COLLATE utf8mb4_unicode_ci AS extrait FROM settings WHERE svalue LIKE '%Sharp%'
UNION ALL SELECT 'Page' COLLATE utf8mb4_unicode_ci, slug COLLATE utf8mb4_unicode_ci, LEFT(title, 120) COLLATE utf8mb4_unicode_ci FROM pages WHERE (content LIKE '%Sharp%' OR title LIKE '%Sharp%') AND slug <> 'mentions-legales'
UNION ALL SELECT 'Service' COLLATE utf8mb4_unicode_ci, slug COLLATE utf8mb4_unicode_ci, LEFT(title, 120) COLLATE utf8mb4_unicode_ci FROM services WHERE content LIKE '%Sharp%' OR title LIKE '%Sharp%' OR short_desc LIKE '%Sharp%'
UNION ALL SELECT 'Bannière' COLLATE utf8mb4_unicode_ci, CONVERT(CAST(id AS CHAR) USING utf8mb4) COLLATE utf8mb4_unicode_ci, LEFT(title, 120) COLLATE utf8mb4_unicode_ci FROM banners WHERE title LIKE '%Sharp%' OR subtitle LIKE '%Sharp%' OR link LIKE '%sharp%';
